 19→  if (!email) throw new Error("ADMIN_EMAIL is required when SELF_HOSTED=true");
 20→  if (!password) throw new Error("ADMIN_PASSWORD is required when SELF_HOSTED=true");
 21→
 22→  return { email, password };
 23→}
 24→
 25→export function buildPersonRecord(
 26→  email: string,
 27→  now: Date,
 28→): {
 29→  name: string;
 30→  contact_email: string;
 31→  email_verified: boolean;
 32→  created_at: Date;
 33→  updated_at: Date;
 34→} {
 35→  return {
 36→    name: "Admin",
 37→    contact_email: email,
 38→    email_verified: true,
 39→    created_at: now,
 40→    updated_at: now,
 41→  };
 42→}
 43→
 44→export function buildAccountRecord(
 45→  personId: string,
 46→  hashedPassword: string,
 47→  now: Date,
 48→): {
 49→  account_id: string;
 50→  provider_id: string;
 51→  password: string;
 52→  created_at: Date;
 53→  updated_at: Date;
 54→} {
 55→  return {
 56→    account_id: personId,
 57→    provider_id: "credential",
 58→    password: hashedPassword,
 59→    created_at: now,
 60→    updated_at: now,
 61→  };
 62→}
 63→
 64→async function seedAdminUser(
 65→  surreal: Surreal,
 66→  config: AdminSeedConfig,
 67→): Promise<void> {
 68→  const [existing] = await surreal.query<[Array<{ id: RecordId }>]>(
 69→    "SELECT id FROM person WHERE contact_email = $email LIMIT 1;",
 70→    { email: config.email },
 71→  );
 72→
 73→  if (existing.length > 0) {
 74→    console.log(`Admin user already exists, skipping seed`);
 75→    return;
 76→  }
 77→
 78→  const hashedPassword = await Bun.password.hash(config.password);
 79→  const now = new Date();
 80→
 81→  const personContent = buildPersonRecord(config.email, now);
 82→
 83→  // Atomic transaction: create person + account together
 84→  const [createdPersons] = await surreal.query<[Array<{ id: RecordId }>]>(
 85→    `BEGIN TRANSACTION;
 86→     LET $person = CREATE person CONTENT $personContent;
 87→     LET $pid = $person[0].id;
 88→     LET $rawId = record::id($pid);
 89→     CREATE type::record("account", $rawId) CONTENT {
 90→       account_id: $rawId,
 91→       provider_id: $providerId,
 92→       password: $hashedPw,
 93→       person_id: $pid,
 94→       created_at: $createdAt,
 95→       updated_at: $updatedAt
 96→     };
 97→     RETURN $person;
 98→     COMMIT TRANSACTION;`,
 99→    {
100→      personContent,
101→      providerId: "credential",
102→      hashedPw: hashedPassword,
103→      createdAt: now,
104→      updatedAt: now,
105→    },
106→  );
107→
108→  console.log(`Admin user seeded: ${config.email}`);
109→}
110→
111→async function maybeSeedAdmin(surreal: Surreal): Promise<void> {
112→  const seedConfig = parseSeedConfig(process.env);
113→  if (!seedConfig) return;
114→  await seedAdminUser(surreal, seedConfig);
115→}
116→
117→// --- Migration runner ---
118→
119→const MIGRATIONS_DIR = join(import.meta.dir, "migrations");
120→const migrationGlob = new Bun.Glob("*.surql");
121→
122→const BOOTSTRAP_SQL = `
123→DEFINE TABLE IF NOT EXISTS _migration SCHEMAFULL;
124→DEFINE FIELD IF NOT EXISTS name ON _migration TYPE string;
125→DEFINE FIELD IF NOT EXISTS applied_at ON _migration TYPE datetime;
126→`;
127→
128→function requireEnv(name: string): string {
129→  const value = process.env[name];
130→  if (!value || value.trim().length === 0) {
131→    throw new Error(`${name} is required`);
132→  }
133→  return value.trim();
134→}
135→
136→async function main() {
137→  const url = requireEnv("SURREAL_URL");
138→  const username = requireEnv("SURREAL_USERNAME");
139→  const password = requireEnv("SURREAL_PASSWORD");
140→  const namespace = requireEnv("SURREAL_NAMESPACE");
141→  const database = requireEnv("SURREAL_DATABASE");
142→
143→  const surreal = new Surreal();
144→  await surreal.connect(url);
145→  await surreal.signin({ username, password });
146→  await surreal.use({ namespace, database });
147→
148→  // Bootstrap migration tracking table
149→  await surreal.query(BOOTSTRAP_SQL);
150→
151→  // Read migration files sorted alphabetically
152→  const files = (await Array.fromAsync(migrationGlob.scan(MIGRATIONS_DIR))).sort();
153→
154→  if (files.length === 0) {
155→    console.log("No migration files found.");
156→    await maybeSeedAdmin(surreal);
157→    await surreal.close();
158→    return;
159→  }
160→
161→  // Get already-applied migrations
162→  const [applied] = await surreal.query<[Array<{ name: string }>]>(
163→    "SELECT name FROM _migration;",
164→  );
165→  const appliedSet = new Set(applied.map((row) => row.name));
166→
167→  const pending = files.filter((f) => !appliedSet.has(f));
168→
169→  if (pending.length === 0) {
170→    console.log("No pending migrations.");
171→    await maybeSeedAdmin(surreal);
172→    await surreal.close();
173→    return;
174→  }
175→
176→  console.log(`${pending.length} pending migration(s):\n`);
177→
178→  for (const file of pending) {
179→    const sql = await Bun.file(join(MIGRATIONS_DIR, file)).text();
180→
181→    try {
182→      const stream = surreal.query(sql).stream();
183→      let stmtIndex = 0;
184→      for await (const frame of stream) {
185→        if (frame.isError()) {
186→          console.error(`✗ Failed: ${file} (statement ${stmtIndex})`);
187→          console.error(`  → ${frame.error.message}`);
188→          await surreal.close();
189→          process.exit(1);
190→        }
191→        stmtIndex++;
192→      }
193→    } catch (err) {
194→      console.error(`✗ Failed: ${file}`);
195→      console.error(err);
196→      await surreal.close();
197→      process.exit(1);
198→    }
199→
200→    const record = new RecordId("_migration", file);
201→    await surreal.query("CREATE $record CONTENT { name: $name, applied_at: time::now() };", {
202→      record,
203→      name: file,
204→    });
205→
206→    console.log(`✓ Applied: ${file}`);
207→  }
208→
209→  console.log(`\nDone. ${pending.length} migration(s) applied.`);
210→  await maybeSeedAdmin(surreal);
211→  await surreal.close();
212→}
